# -*- coding: utf-8 -*-
"""
AquaPulse Multi-Container Testbed self-extracting installer.
Run this script locally to recreate the full multi-container dockerized environment.
"""
import base64
import os
import zipfile

B64_DATA = """"""

def main():
    print("[*] Extracting AquaPulse Multi-Container Testbed...")
    zip_bytes = base64.b64decode(B64_DATA)
    zip_filename = "aquapulse_testbed.zip"
    
    with open(zip_filename, "wb") as f:
        f.write(zip_bytes)
    
    print("[*] Extracting files...")
    with zipfile.ZipFile(zip_filename, "r") as zip_ref:
        zip_ref.extractall(".")
        
    print("[+] Extraction complete!")
    print("[*] Directory 'aquapulse_testbed' has been successfully created.")
    print("[*] Read 'aquapulse_testbed/README.md' to launch the docker-compose grid!")
    
    # Clean up the temporary zip file
    try:
        os.remove(zip_filename)
    except Exception:
        pass

if __name__ == '__main__':
    main()
